// MonthlySales runs the query of its name in queries.sql.
func (r Order) MonthlySales(ctx context.Context, since time.Time) ([]repository.MonthSales, error) {
	const q = `SELECT date_trunc('month', o.placed_at) AS month,
       count(DISTINCT o.id) AS orders,
       sum(l.quantity * p.price)::bigint AS revenue
FROM orders o
JOIN order_lines l ON l.order_id = o.id
JOIN products p ON p.sku = l.sku
WHERE o.placed_at >= $1 AND o.status <> 'canceled'
GROUP BY 1
ORDER BY 1`
	rows, err := r.db.Query(ctx, q, since)
	if err != nil {
		return nil, r.mapError(orderOperationMonthlySales, fmt.Errorf("query MonthlySales: %w", err))
	}
	defer rows.Close()
	out := []repository.MonthSales{}
	var row repository.MonthSales
	dest := []any{&row.Month, &row.Orders, &row.Revenue}
	for rows.Next() {
		row = repository.MonthSales{}
		if err := rows.Scan(dest...); err != nil {
			return nil, r.mapError(orderOperationMonthlySales, fmt.Errorf("query MonthlySales: %w", err))
		}
		out = append(out, row)
	}
	if err := rows.Err(); err != nil {
		return nil, r.mapError(orderOperationMonthlySales, fmt.Errorf("query MonthlySales: %w", err))
	}
	return out, nil
}

// Fulfillment implements repository.Fulfillment on PostgreSQL through pgx.
type Fulfillment struct{ db kDatabase }

func newFulfillment(db DBTX, opts ...option.Option) Fulfillment {
	return Fulfillment{db: kDatabase{dbtx: db, options: impl.NewOptions(opts...)}}
}

// NewFulfillment returns Fulfillment running on db.
func NewFulfillment(db DBTX, opts ...option.Option) Fulfillment { return newFulfillment(db, opts...) }

var _ repository.Fulfillment = Fulfillment{}

func (r Fulfillment) GetForUpdate(ctx context.Context, id model.OrderID) (model.Order, error) {
	if !impl.InTransaction[kpgx.DBTX](r.db.dbtx) {
		return model.Order{}, fmt.Errorf("orm: GetForUpdate needs a transaction to hold its lock: give the repository a pgx.Tx, or a DBTX wrapping one with an Unwrap method returning it")
	}
	const q = `SELECT id, customer_id, status, placed_at, note FROM orders WHERE id = $1 FOR UPDATE`
	var row model.Order
	var nullableMemo sql.Null[string]
	err := r.db.QueryRow(ctx, q, id).Scan(&row.ID, &row.CustomerID, &row.Status, &row.PlacedAt, &nullableMemo)
	if errors.Is(err, pgx.ErrNoRows) {
		return model.Order{}, fmt.Errorf("orders with id %v: %w", id, orm.ErrNotFound)
	}
	if err != nil {
		return model.Order{}, fmt.Errorf(`read orders: %w`, err)
	}
	row.Memo = nullableMemo.V
	return row, nil
}

func (r Fulfillment) FirstToShip(ctx context.Context, s ...scopes.Order) (model.Order, error) {
	if !impl.InTransaction[kpgx.DBTX](r.db.dbtx) {
		return model.Order{}, fmt.Errorf("orm: FirstToShip needs a transaction to hold its lock: give the repository a pgx.Tx, or a DBTX wrapping one with an Unwrap method returning it")
	}
	qs := make([]impl.Of[model.Order], len(s))
	for i, x := range s {
		qs[i] = impl.Of[model.Order](x.Of())
	}
	q := impl.Combine(qs...)
	if err := q.Forward("FirstToShip"); err != nil {
		return model.Order{}, err
	}
	q = q.DefaultOrder([]string{`id`}).Limit(1)
	rows, err := kSelectOrders(ctx, r.db, q, ` FOR UPDATE SKIP LOCKED`)
	if err != nil {
		return model.Order{}, err
	}
	if len(rows) == 0 {
		return model.Order{}, fmt.Errorf("no row of orders matches: %w", orm.ErrNotFound)
	}
	return rows[0], nil
}

func (r Fulfillment) InsertShipment(ctx context.Context, s model.Shipment) error {
	const q = `INSERT INTO shipments (order_id, carrier, tracking)
VALUES ($1, $2, $3)`
	if _, err := r.db.Exec(ctx, q, s.OrderID, s.Carrier, s.Tracking); err != nil {
		return fmt.Errorf("insert into shipments: %w", err)
	}
	return nil
}

func (r Fulfillment) Update(ctx context.Context, o model.Order) error {
	const q = `UPDATE orders
SET customer_id = $1, status = $2, placed_at = $3, note = $4
WHERE id = $5`
	tag, err := r.db.Exec(ctx, q, o.CustomerID, o.Status, o.PlacedAt, sql.Null[string]{V: o.Memo, Valid: o.Memo != ""}, o.ID)
	if err != nil {
		return fmt.Errorf("update orders: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("orders with id %v: %w", o.ID, orm.ErrNotFound)
	}
	return nil
}

